def probability(target):
    memo = {}
    def solve(state, next_ball):
        key = (state, next_ball)
        if key in memo:
            return memo[key]
        first, second, third = state

        # Piston 1: first ball is ejected.
        branch1 = 1.0 if first == target else solve((second, third, next_ball), next_ball + 1)

        # Piston 2: second ball is ejected; first is collateral-discarded.
        if second == target:
            branch2 = 1.0
        elif first == target:
            branch2 = 0.0
        else:
            branch2 = solve((third, next_ball, next_ball + 1), next_ball + 2)

        # Piston 3: third ball is ejected; first is collateral-discarded.
        if third == target:
            branch3 = 1.0
        elif first == target:
            branch3 = 0.0
        else:
            branch3 = solve((second, next_ball, next_ball + 1), next_ball + 2)

        memo[key] = (branch1 + branch2 + branch3) / 3.0
        return memo[key]

    return solve((1, 2, 3), 4)

