context_status = knowledge_check.get("scope")

def ball_probability(target):
    memo = {}

    def rec(platform, next_ball):
        key = (platform, next_ball)
        if key in memo:
            return memo[key]

        a, b, c = platform

        # First piston: a is ejected.
        p1 = 1.0 if a == target else rec((b, c, next_ball), next_ball + 1)

        # Second piston: b is ejected; a is discarded.
        if b == target:
            p2 = 1.0
        elif a == target:
            p2 = 0.0
        else:
            p2 = rec((c, next_ball, next_ball + 1), next_ball + 2)

        # Third piston: c is ejected; a is discarded.
        if c == target:
            p3 = 1.0
        elif a == target:
            p3 = 0.0
        else:
            p3 = rec((b, next_ball, next_ball + 1), next_ball + 2)

        memo[key] = (p1 + p2 + p3) / 3.0
        return memo[key]

    return rec((1, 2, 3), 4)

